import React, { useEffect, useState } from "react";
import {
  View, Text, StyleSheet, TextInput, TouchableOpacity,
  ScrollView, Alert, SafeAreaView, KeyboardAvoidingView,
  Platform, StatusBar, ActivityIndicator
} from "react-native";
import axios from "axios";
import { useRouter } from "expo-router";
import { Feather } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";

const COLORS = {
  dark: "#0a3d2e",    // Verde Glaze
  accent: "#1f6f54",  
  silver: "#94a3b8",  
  bg: "#fcfdfd",      
  border: "#f1f5f9",  
  white: "#ffffff"
};

export default function Perfil() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [cargandoDatos, setCargandoDatos] = useState(true);
  
  const [usuario, setUsuario] = useState({
    id_usuario: null,
    nombre_completo: "",
    correo: "",
    celular: "",
    direccion: ""
  });

  const [passwordData, setPasswordData] = useState({
    password_actual: "", 
    password: ""
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    try {
      const usuarioRaw = await AsyncStorage.getItem("usuario");
      if (!usuarioRaw) return router.replace("/login");
      const user = JSON.parse(usuarioRaw);
      const res = await axios.get(`http://192.168.1.9:3000/api/usuarios/${user.id_usuario}`);
      setUsuario(res.data);
    } catch (error) {
      console.error("Error al cargar:", error);
    } finally {
      setCargandoDatos(false);
    }
  };

  const guardarCambios = async () => {
    try {
      setLoading(true);
      const payload = {
        correo: usuario.correo.trim(),
        celular: String(usuario.celular).trim(),
        direccion: usuario.direccion ? usuario.direccion.trim() : ""
      };
      await axios.put(`http://192.168.1.9:3000/api/usuarios/actualizar/${usuario.id_usuario}`, payload);
      Alert.alert("Glaze", "Datos actualizados.");
    } catch (error) {
      Alert.alert("Error", "No se pudo actualizar.");
    } finally {
      setLoading(false);
    }
  };

  if (cargandoDatos) return <View style={styles.center}><ActivityIndicator color={COLORS.dark} /></View>;

  return (
    <SafeAreaView style={styles.mainWrapper}>
      <StatusBar barStyle="dark-content" />
      <View style={styles.navHeader}>
        <TouchableOpacity onPress={() => router.back()}><Feather name="chevron-left" size={24} color={COLORS.dark} /></TouchableOpacity>
        <Text style={styles.navTitle}>CUENTA PRIVADA</Text>
        <View style={{ width: 24 }} />
      </View>

      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={{ flex: 1 }}>
        <ScrollView style={styles.container} showsVerticalScrollIndicator={false}>
          
          <View style={styles.headerSection}>
            <Text style={styles.brandTitle}>Gestión de Perfil</Text>
            <View style={styles.accentLine} />
            <Text style={styles.brandSubtitle}>CONFIGURACIÓN DE SEGURIDAD Y DATOS</Text>
          </View>

          {/* CARD BLANCA: INFORMACIÓN DEL TITULAR */}
          <View style={styles.glazeCard}>
            <View style={styles.sideIndicator} />
            <View style={styles.cardPadding}>
              <Text style={styles.sectionLabel}>INFORMACIÓN DEL TITULAR</Text>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>NOMBRE COMPLETO (NO EDITABLE)</Text>
                <TextInput style={[styles.input, styles.inputBlocked]} value={usuario.nombre_completo.toUpperCase()} editable={false} />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>CORREO ELECTRÓNICO</Text>
                <TextInput 
                  style={styles.input} 
                  value={usuario.correo} 
                  onChangeText={(t) => setUsuario({...usuario, correo: t})}
                />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>TELÉFONO DE CONTACTO</Text>
                <TextInput 
                  style={styles.input} 
                  value={usuario.celular} 
                  onChangeText={(t) => setUsuario({...usuario, celular: t})}
                  keyboardType="numeric"
                />
              </View>

              {/* AQUÍ ESTÁ EL CAMPO DE DIRECCIÓN AHORA SÍ DENTRO DE LA CARD */}
              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>DIRECCIÓN DE RESIDENCIA</Text>
                <TextInput 
                  style={styles.input} 
                  value={usuario.direccion} 
                  onChangeText={(t) => setUsuario({...usuario, direccion: t})}
                  placeholder="Calle, Carrera, Ciudad..."
                />
              </View>

              <TouchableOpacity style={styles.btnMain} onPress={guardarCambios} disabled={loading}>
                {loading ? <ActivityIndicator color="white" /> : <Text style={styles.btnMainText}>GUARDAR CAMBIOS</Text>}
              </TouchableOpacity>
            </View>
          </View>

          {/* CARD BLANCA: SEGURIDAD */}
          <View style={styles.glazeCard}>
            <View style={[styles.sideIndicator, {backgroundColor: COLORS.silver}]} />
            <View style={styles.cardPadding}>
              <Text style={styles.sectionLabel}>SEGURIDAD DE LA BÓVEDA</Text>
              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>CONTRASEÑA ACTUAL</Text>
                <TextInput 
                    style={styles.input} 
                    secureTextEntry 
                    value={passwordData.password_actual}
                    onChangeText={(t) => setPasswordData({...passwordData, password_actual: t})}
                />
              </View>
              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>NUEVA CONTRASEÑA</Text>
                <TextInput 
                    style={styles.input} 
                    secureTextEntry 
                    value={passwordData.password}
                    onChangeText={(t) => setPasswordData({...passwordData, password: t})}
                />
              </View>
              <TouchableOpacity style={styles.btnSecondary}>
                <Text style={styles.btnSecondaryText}>ACTUALIZAR CREDENCIALES</Text>
              </TouchableOpacity>
            </View>
          </View>

          <View style={{ height: 30 }} />
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  mainWrapper: { flex: 1, backgroundColor: COLORS.bg },
  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  container: { paddingHorizontal: 20 },
  navHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', padding: 20 },
  navTitle: { fontSize: 10, letterSpacing: 2, fontWeight: '900', color: COLORS.dark },
  headerSection: { marginBottom: 25 },
  brandTitle: { fontSize: 28, fontWeight: '300', color: COLORS.dark },
